import{_ as n,c as s,o as e,ag as i}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Ansible for Matrix Deployment","description":"","frontmatter":{"title":"Ansible for Matrix Deployment"},"headers":[],"relativePath":"matrix/ansible-for-matrix-deployment.md","filePath":"matrix/ansible-for-matrix-deployment.md","lastUpdated":null}'),l={name:"matrix/ansible-for-matrix-deployment.md"};function r(t,a,p,o,b,d){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="ansible-for-matrix-deployment" tabindex="-1">Ansible for Matrix Deployment <a class="header-anchor" href="#ansible-for-matrix-deployment" aria-label="Permalink to &quot;Ansible for Matrix Deployment&quot;">​</a></h1><h2 id="installing-ansible-for-matrix-deployment" tabindex="-1">Installing Ansible for Matrix Deployment <a class="header-anchor" href="#installing-ansible-for-matrix-deployment" aria-label="Permalink to &quot;Installing Ansible for Matrix Deployment&quot;">​</a></h2><p>Return to <a href="/server-guides/">Guides</a>.</p><p>If you are installing on an LXC, see the <a href="/server-guides/proxmox-linux-container-lxc-setup.html">Linux Container LXC Setup</a> guide first. Set DNS using the <a href="https://github.com/spantaleev/matrix-docker-ansible-deploy/blob/master/docs/configuring-dns.md" target="_blank" rel="noreferrer">DNS Guide</a>.</p><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><h3 id="install-ansible" tabindex="-1">Install Ansible <a class="header-anchor" href="#install-ansible" aria-label="Permalink to &quot;Install Ansible&quot;">​</a></h3><p>Refer to the official <a href="https://docs.ansible.com/ansible/latest/installation_guide/intro_installation.html#installing-ansible-on-ubuntu" target="_blank" rel="noreferrer">Ansible Installation Guide</a>.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>wget -qO - &#39;https://proget.makedeb.org/debian-feeds/prebuilt-mpr.pub&#39; | gpg --dearmor | sudo tee /usr/share/keyrings/prebuilt-mpr-archive-keyring.gpg 1&gt; /dev/null</span></span>
<span class="line"><span>echo &quot;deb [signed-by=/usr/share/keyrings/prebuilt-mpr-archive-keyring.gpg](arch=amd64) https://proget.makedeb.org prebuilt-mpr $(lsb_release -cs)&quot; | sudo tee /etc/apt/sources.list.d/prebuilt-mpr.list</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo apt install just</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo apt install -y python3-pip # Install pip</span></span>
<span class="line"><span>python3 -m pip install --user ansible # Use pip to install Ansible</span></span>
<span class="line"><span>pip install passlib</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h3 id="running-ansible" tabindex="-1">Running Ansible <a class="header-anchor" href="#running-ansible" aria-label="Permalink to &quot;Running Ansible&quot;">​</a></h3><p>After DNS is fully configured and ready:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>make roles</span></span>
<span class="line"><span>ansible-playbook -i inventory/hosts setup.yml --tags=setup-all,start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="vars-creation" tabindex="-1">Vars Creation <a class="header-anchor" href="#vars-creation" aria-label="Permalink to &quot;Vars Creation&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>echo &quot;domain.tld: matrix.&quot;</span></span>
<span class="line"><span>read domain</span></span>
<span class="line"><span>echo &quot;remote IP address: &quot;</span></span>
<span class="line"><span>read remote_ip</span></span>
<span class="line"><span>git clone https://github.com/spantaleev/matrix-docker-ansible-deploy.git</span></span>
<span class="line"><span>cd ./matrix-docker-ansible-deploy</span></span>
<span class="line"><span>mkdir inventory/host_vars/matrix.$domain</span></span>
<span class="line"><span>cp examples/vars.yml inventory/host_vars/matrix.$domain/vars.yml</span></span>
<span class="line"><span>cp examples/hosts inventory/hosts</span></span>
<span class="line"><span>sed &#39;s/YOUR_BARE_DOMAIN_NAME_HERE/$domain/g&#39; inventory/host_vars/matrix.$domain/vars.yml</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h3 id="vars-configuration" tabindex="-1">VARS Configuration <a class="header-anchor" href="#vars-configuration" aria-label="Permalink to &quot;VARS Configuration&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>sed &#39;s/synapse/dendrite/&#39; inventory/host_vars/matrix.$domain/vars.yml</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><ul><li><p><a href="https://docs.ansible.com/ansible/latest/installation_guide/intro_installation.html#installing-ansible-on-ubuntu" target="_blank" rel="noreferrer">Ansible Installation Documentation</a></p></li><li><p><a href="https://github.com/spantaleev/matrix-docker-ansible-deploy" target="_blank" rel="noreferrer">Matrix Docker Ansible Deploy Repository</a></p></li><li><p><a href="https://github.com/spantaleev/matrix-docker-ansible-deploy/blob/master/docs/configuring-dns.md" target="_blank" rel="noreferrer">DNS Guide</a></p></li></ul>`,17)])])}const m=n(l,[["render",r]]);export{u as __pageData,m as default};
